/* Progressive motion: native scroll, compositor-only transforms, reduced-motion support. */
(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)');const progress=document.createElement('div');progress.className='scroll-progress';progress.setAttribute('aria-hidden','true');document.body.append(progress);let pending=false;const phone=document.querySelector('.hero-phone');function update(){pending=false;const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?Math.min(1,Math.max(0,scrollY/max)):0})`;if(phone&&!reduced.matches&&!document.body.classList.contains('motion-paused'))phone.style.transform=`translateY(${Math.min(scrollY*.09,45)}px) rotate(${8-Math.min(scrollY*.008,5)}deg)`;}function schedule(){if(!pending){pending=true;requestAnimationFrame(update)}}addEventListener('scroll',schedule,{passive:true});addEventListener('resize',schedule);reduced.addEventListener('change',()=>{if(reduced.matches&&phone)phone.style.transform='';schedule()});update();if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;if(!reduced.matches&&!document.body.classList.contains('motion-paused'))e.target.classList.add('motion-reveal');observer.unobserve(e.target)}),{threshold:.12});document.querySelectorAll('.hub-heading,.story-introduction,.operations-intro,.voice-grid article,.feature-grid article,.page-intro,.detail-hero>div:first-child,.special-heading').forEach(el=>observer.observe(el));}})();
